#ifndef DBTEXT_H
#define DBTEXT_H

#include <QCoreApplication>
#include <QString>

// ================================================================
//  DbText
//  Texts of the database are in English (some are also keys used by
//  the code: resource and component names). They are translated only
//  when they are shown, in the "Database" context of stargate_fr.ts
//  (list generated by tools/i18n/extract_db_texts.py).
// ================================================================

namespace DbText {

inline QString tr(const QString &text)
{
    if (text.isEmpty())
        return text;
    return QCoreApplication::translate("Database", text.toUtf8().constData());
}

} // namespace DbText

#endif // DBTEXT_H
